    /**
     * Returns the built-in item type with the supplied identifier.
     *
     * @param id item identifier
     * @return matching built-in item type, if present
     */
    public static Optional<ItemType> get(Identifier id) {
        return TYPES.get(id);
    }

    /**
     * Returns all built-in item types in declaration order.
     *
     * @return built-in item types
     */
    public static List<ItemType> values() {
        return TYPES.values();
    }

    private static ItemType type(String id) {
        return TYPES.register(ItemType.of(Identifier.parse(id)));
    }
